input.new_string:
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/** Writes the audit row for a workspace lifecycle event. Subject is the workspace. */
async function recordOrganizationLifecycle(
  org: Organization,
  action: "organization.deleted" | "organization.restored",
  actorId: UserId,
): Promise<void> {
  const verb = action === "organization.deleted" ? "Deleted" : "Restored";
  await record(org.id, action, {
    actorId,
    subjectKind: "organization",
    subjectId: org.id,
    projectId: null,
    summary: `${verb} workspace ${org.slug}`,
  });
}

