/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

input.new_string:
/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace stays reserved
 * and inert until the retention window closes; deleting it again conflicts.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  assertNotArchived("Organization", org.id, org);

  const archived = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...envelope(archived.id, actor.userId),
    slug: archived.slug,
  });
  await recordOrganizationLifecycle(archived, "organization.deleted", actor.userId);

  return archived;
}

/**
 * Brings a deleted workspace back. No `Actor` can be resolved for a deleted
 * workspace, so the caller is identified by user id. A live workspace is
 * returned unchanged and publishes nothing.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);

  if (
    org.archivedAt !== null &&
    isDeletedWorkspaceExpired(org.archivedAt, new Date())
  ) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(restored.id, userId),
    slug: restored.slug,
  });
  await recordOrganizationLifecycle(restored, "organization.restored", userId);

  return restored;
}

