/**
 * Temporary behavioural check for the workspace deletion grace period.
 * Deleted after the check passes.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { count, eq } from "drizzle-orm";
import {
  DELETED_WORKSPACE_RETENTION_DAYS,
  isDeletedWorkspaceExpired,
} from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { newId } from "@/lib/id";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityFilterSchema } from "@/schemas/activity";
import {
  activityEvents,
  attachments,
  comments,
  getDb,
  invitations,
  invoices,
  issueLabels,
  issues,
  labels,
  members,
  notificationPreferences,
  notifications,
  organizationUsage,
  organizations,
  projectMembers,
  projects,
  rateLimitBuckets,
  searchIndex,
  sessions,
  subscriptions,
  webhookDeliveries,
  webhookEndpoints,
} from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import {
  resetOverdueTracking,
  runOverdueIssueJob,
} from "@/server/jobs/overdue-issue-job";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { insertActivity, listActivity } from "@/server/repositories/activity-repository";
import { insertInvoice } from "@/server/repositories/invoice-repository";
import { insertInvitation } from "@/server/repositories/invitation-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { upsertPreference } from "@/server/repositories/notification-preference-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import {
  insertEndpoint,
  enqueueDelivery,
} from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import { acceptInvitation } from "@/server/services/invitation-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  listOrganizationsForUser,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg, switchActiveOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import * as issueService from "@/server/services/issue-service";
import type { Tenant } from "./_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import type { SessionPrincipal } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function principal(tenant: Tenant): SessionPrincipal {
  return {
    userId: tenant.userIds.owner,
    email: `owner@${tenant.org.slug}.test`,
    activeOrgId: tenant.org.id,
    expiresAt: toIsoTimestamp(new Date(Date.now() + MS_PER_DAY)),
  };
}

async function rowsFor(table: { orgId: unknown }, orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(table as never)
    .where(eq((table as { orgId: never }).orgId, orgId))
    .get() as { value: number } | undefined;
  return row?.value ?? 0;
}

describe("retention constant", () => {
  it("expires at exactly 30 × 24h and not a millisecond sooner", () => {
    expect(DELETED_WORKSPACE_RETENTION_DAYS).toBe(30);
    const deleted = "2026-01-01T00:00:00.000Z";
    const exactly = new Date(Date.parse(deleted) + 30 * MS_PER_DAY);
    expect(isDeletedWorkspaceExpired(deleted, exactly)).toBe(true);
    expect(
      isDeletedWorkspaceExpired(deleted, new Date(exactly.getTime() - 1)),
    ).toBe(false);
    expect(activityFilterSchema.parse({
      orgId: "01HZZZORGORGORGORGORGORGA",
      action: ["organization.deleted", "organization.restored"],
      limit: 25,
      cursor: null,
    }).action).toEqual(["organization.deleted", "organization.restored"]);
  });
});

describe("delete, inert window, restore", () => {
  it("keeps a deleted workspace frozen, then brings it back for its owner", async () => {
    const tenant = await createTenant("grace-live", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const beforeUsage = await usageRepo.getUsage(tenant.org.id);

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Still due",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );

    const token = "grace-invite-token";
    const invitation = await insertInvitation(
      tenant.org.id,
      {
        email: "new@grace-live.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.owner,
      hashToken(token),
    );

    const endpoint = await insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created"],
      },
      "secret",
    );
    const delivery = await enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );

    await upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: true,
      digestOnly: true,
    });
    const digestNote = await notificationRepo.insertNotification(tenant.org.id, {
      recipientId: tenant.userIds.admin,
      kind: "issue_assigned",
      title: "Digest me",
      body: "body",
      href: "/issues/1",
      actorId: null,
      channels: ["in_app"],
    });

    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "project",
      tenant.project.id,
      "frozen-index",
      tenant.project.id,
    );

    const oldActivity = await insertActivity({
      orgId: tenant.org.id,
      action: "issue.created",
      actorId: tenant.userIds.owner,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: tenant.project.id,
      summary: "old row",
      metadata: {},
      occurredAt: toIsoTimestamp(new Date(Date.now() - 400 * MS_PER_DAY)),
    });

    const liveNotify = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.admin],
      {
        title: "Live",
        body: "body",
        href: "/issues/1",
        actorId: tenant.userIds.owner,
      },
    );
    expect(liveNotify).toHaveLength(1);

    const deletedEvents: string[] = [];
    const offDeleted = subscribe("organization.deleted", (payload) => {
      deletedEvents.push(`${payload.actorId}:${payload.slug}`);
    });

    const deleted = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();
    expect(deletedEvents).toEqual([
      `${tenant.userIds.owner}:${tenant.org.slug}`,
    ]);
    offDeleted();

    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await listOrganizationsForUser(tenant.userIds.owner)).toEqual([]);
    expect(await orgRepo.findOrgBySlug(tenant.org.slug)).toBeNull();
    expect(await orgRepo.listTakenOrgSlugs(tenant.org.slug)).toContain(
      tenant.org.slug,
    );
    expect(
      await resolveActorForOrg(principal(tenant), tenant.org.slug),
    ).toBeNull();
    await expect(
      switchActiveOrg(principal(tenant), { orgId: tenant.org.id }),
    ).rejects.toThrow(/not a member/);

    const createdWhileDeleted = await createOrganization(tenant.userIds.owner, {
      name: "Grace live two",
      slug: tenant.org.slug,
      plan: "free",
    });
    expect(createdWhileDeleted.slug).not.toBe(tenant.org.slug);

    expect(
      await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
        title: "Nope",
        body: "body",
        href: "/issues/1",
        actorId: tenant.userIds.owner,
      }),
    ).toEqual([]);

    await expect(
      acceptInvitation(tenant.userIds.admin, { token }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const stillPending = getDb()
      .select()
      .from(invitations)
      .where(eq(invitations.id, invitation.id))
      .get();
    expect(stillPending?.acceptedAt).toBeNull();
    expect(stillPending?.revokedAt).toBeNull();

    resetOverdueTracking();
    const overdueSeen: string[] = [];
    const offOverdue = subscribe("issue.overdue", (payload) => {
      overdueSeen.push(payload.issueId);
    });
    await runOverdueIssueJob(new Date());
    expect(overdueSeen).not.toContain(issue.id);
    offOverdue();

    await runUsageRollupJob(new Date());
    expect((await usageRepo.getUsage(tenant.org.id)).measuredAt).toBe(
      beforeUsage.measuredAt,
    );

    await runTrialExpiryJob(new Date("2026-01-01T00:00:00.000Z"));

    await runWebhookDeliveryJob(new Date());
    const failedDelivery = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.id, delivery.id))
      .get();
    expect(failedDelivery?.status).toBe("failed");
    expect(failedDelivery?.lastError).toBe("workspace is deleted");

    const reindex = await runSearchReindexJob(tenant.org.id);
    expect(reindex.processed).toBe(0);
    const frozen = getDb()
      .select()
      .from(searchIndex)
      .where(eq(searchIndex.orgId, tenant.org.id))
      .all();
    expect(frozen.some((row) => row.content === "frozen-index")).toBe(true);

    const digest = await runDigestEmailJob(new Date("2026-06-01T07:00:00.000Z"));
    expect(digest.processed).toBe(0);
    const digestRow = getDb()
      .select()
      .from(notifications)
      .where(eq(notifications.id, digestNote.id))
      .get();
    expect(digestRow?.readAt).toBeNull();

    await runCleanupArchivedJob(new Date());
    expect(
      await orgRepo.findOrgById(tenant.org.id),
    ).toMatchObject({ id: tenant.org.id });
    const oldStillThere = getDb()
      .select()
      .from(activityEvents)
      .where(eq(activityEvents.id, oldActivity.id))
      .get();
    expect(oldStillThere).toBeTruthy();

    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "organization.deleted",
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });

    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stranger = await userRepo.insertUser({
      email: "stranger@grace-live.test",
      name: "Stranger",
      passwordHash: "seed",
    });
    await expect(
      restoreOrganization(stranger.id, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(tenant.userIds.owner, "01HZZZMISSINGORGORGORGORG" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);

    const restoredEvents: string[] = [];
    const offRestored = subscribe("organization.restored", (payload) => {
      restoredEvents.push(`${payload.actorId}:${payload.slug}`);
    });
    const restored = await restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );
    expect(restored.archivedAt).toBeNull();
    expect(restored.slug).toBe(tenant.org.slug);
    expect(restoredEvents).toEqual([
      `${tenant.userIds.owner}:${tenant.org.slug}`,
    ]);
    offRestored();

    const restoredAudit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.restored"],
      limit: 25,
      cursor: null,
    });
    expect(restoredAudit.items).toHaveLength(1);
    expect(restoredAudit.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });

    expect(
      (await listOrganizationsForUser(tenant.userIds.owner)).some(
        (org) => org.id === tenant.org.id,
      ),
    ).toBe(true);
    expect(
      await resolveActorForOrg(principal(tenant), tenant.org.slug),
    ).toMatchObject({ userId: tenant.userIds.owner, role: "owner" });

    expect(
      await notify(tenant.org.id, "comment_created", [tenant.userIds.admin], {
        title: "Back",
        body: "body",
        href: "/issues/1",
        actorId: tenant.userIds.owner,
      }),
    ).toHaveLength(1);

    resetOverdueTracking();
    const resumed: string[] = [];
    const offResumed = subscribe("issue.overdue", (payload) => {
      resumed.push(payload.issueId);
    });
    await runOverdueIssueJob(new Date());
    expect(resumed).toContain(issue.id);
    offResumed();

    const rolled = await runUsageRollupJob(new Date());
    expect(rolled.processed).toBeGreaterThan(0);
    expect((await usageRepo.getUsage(tenant.org.id)).measuredAt).not.toBe(
      beforeUsage.measuredAt,
    );

    const reindexed = await runSearchReindexJob(tenant.org.id);
    expect(reindexed.processed).toBeGreaterThan(0);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await createTenant("grace-not-deleted", "growth");
    const seen: unknown[] = [];
    const off = subscribe("organization.restored", (payload) => {
      seen.push(payload);
    });
    const result = await restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );
    expect(result).toEqual(tenant.org);
    expect(seen).toEqual([]);
    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.restored"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(0);
    off();
  });
});

describe("window and purge", () => {
  it("treats a closed window as gone and purges only expired deletions", async () => {
    const expired = await createTenant("grace-expired", "growth");
    const young = await createTenant("grace-young", "growth");
    const live = await createTenant("grace-kept", "free");
    await usageRepo.recomputeUsage(live.org.id);

    await deleteOrganization(expired.actors.owner, {
      orgId: expired.org.id,
      confirmSlug: expired.org.slug,
    });
    await deleteOrganization(young.actors.owner, {
      orgId: young.org.id,
      confirmSlug: young.org.slug,
    });

    const now = new Date("2026-08-01T00:00:00.000Z");
    const expiredAt = toIsoTimestamp(new Date(now.getTime() - 30 * MS_PER_DAY));
    const youngAt = toIsoTimestamp(new Date(now.getTime() - 30 * MS_PER_DAY + 1));
    getDb()
      .update(organizations)
      .set({ archivedAt: expiredAt })
      .where(eq(organizations.id, expired.org.id))
      .run();
    getDb()
      .update(organizations)
      .set({ archivedAt: youngAt })
      .where(eq(organizations.id, young.org.id))
      .run();

    await expect(
      restoreOrganization(expired.userIds.owner, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(expired.userIds.admin, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const youngRestored = await restoreOrganization(
      young.userIds.owner,
      young.org.id,
    );
    expect(youngRestored.archivedAt).toBeNull();
    await deleteOrganization(young.actors.owner, {
      orgId: young.org.id,
      confirmSlug: young.org.slug,
    });
    getDb()
      .update(organizations)
      .set({ archivedAt: youngAt })
      .where(eq(organizations.id, young.org.id))
      .run();

    await seedBelongings(expired);
    await seedBelongings(young);

    const sessionHash = "grace-session-hash";
    await sessionRepo.createSession(
      expired.userIds.owner,
      sessionHash,
      toIsoTimestamp(new Date(now.getTime() + MS_PER_DAY)),
    );
    getDb()
      .update(sessions)
      .set({ activeOrgId: expired.org.id })
      .where(eq(sessions.tokenHash, sessionHash))
      .run();

    const oldStamp = toIsoTimestamp(new Date(now.getTime() - 40 * MS_PER_DAY));
    const recentStamp = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
    const oldAudit = await insertActivity({
      orgId: live.org.id,
      action: "issue.created",
      actorId: live.userIds.owner,
      subjectKind: "issue",
      subjectId: "old-live",
      projectId: live.project.id,
      summary: "old",
      metadata: {},
      occurredAt: oldStamp,
    });
    const recentAudit = await insertActivity({
      orgId: live.org.id,
      action: "issue.created",
      actorId: live.userIds.owner,
      subjectKind: "issue",
      subjectId: "recent-live",
      projectId: live.project.id,
      summary: "recent",
      metadata: {},
      occurredAt: recentStamp,
    });
    const liveIssue = await issueService.createIssue(
      live.actors.member,
      issueInput(live.org.id, live.project.id, { title: "Archive me" }),
    );
    await issueService.archiveIssue(live.actors.member, live.org.id, liveIssue.id);
    getDb()
      .update(issues)
      .set({ archivedAt: oldStamp })
      .where(eq(issues.id, liveIssue.id))
      .run();
    await searchRepo.upsertSearchDocument(
      live.org.id,
      "issue",
      liveIssue.id,
      "drop-me",
      live.project.id,
    );

    await runCleanupArchivedJob(now);

    expect(await orgRepo.findOrgById(expired.org.id)).toBeNull();
    expect(await userRepo.findUserById(expired.userIds.owner)).not.toBeNull();
    for (const table of [
      members,
      invitations,
      projects,
      projectMembers,
      issues,
      labels,
      issueLabels,
      comments,
      attachments,
      notifications,
      notificationPreferences,
      activityEvents,
      subscriptions,
      invoices,
      webhookEndpoints,
      webhookDeliveries,
      searchIndex,
      rateLimitBuckets,
      organizationUsage,
    ]) {
      expect(await rowsFor(table, expired.org.id)).toBe(0);
    }
    const session = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.tokenHash, sessionHash))
      .get();
    expect(session).toBeTruthy();
    expect(session?.activeOrgId).toBeNull();

    await expect(
      restoreOrganization(expired.userIds.owner, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reclaimed = await createOrganization(expired.userIds.owner, {
      name: "Grace expired again",
      slug: expired.org.slug,
      plan: "free",
    });
    expect(reclaimed.slug).toBe(expired.org.slug);

    expect((await orgRepo.findOrgById(young.org.id))?.archivedAt).toBe(youngAt);
    expect(await rowsFor(members, young.org.id)).toBeGreaterThan(0);
    expect(await rowsFor(projects, young.org.id)).toBeGreaterThan(0);
    expect(await orgRepo.listTakenOrgSlugs(young.org.slug)).toContain(
      young.org.slug,
    );

    expect(await orgRepo.findOrgById(live.org.id)).toBeTruthy();
    expect(
      getDb().select().from(activityEvents).where(eq(activityEvents.id, oldAudit.id)).get(),
    ).toBeUndefined();
    expect(
      getDb().select().from(activityEvents).where(eq(activityEvents.id, recentAudit.id)).get(),
    ).toBeTruthy();
    expect(
      getDb().select().from(issues).where(eq(issues.id, liveIssue.id)).get(),
    ).toBeTruthy();
    expect(
      getDb()
        .select()
        .from(searchIndex)
        .where(eq(searchIndex.subjectId, liveIssue.id))
        .get(),
    ).toBeUndefined();
  });

  it("does not downgrade an ended trial on a deleted workspace", async () => {
    const deleted = await smallTrial("grace-trial-deleted");
    const live = await smallTrial("grace-trial-live");
