    expect((await subscriptionRepo.findSubscription(deleted.orgId))?.status).toBe(
      "trialing",
    );
    expect((await subscriptionRepo.findSubscription(live.orgId))?.plan).toBe("free");
    expect((await subscriptionRepo.findSubscription(live.orgId))?.status).toBe(
      "active",
    );
  });
});

async function smallTrial(slug: string): Promise<{
  orgId: OrgId;
  slug: string;
  actor: Tenant["actors"]["owner"];
}> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });
  const org = await orgRepo.insertOrg(
    { name: slug, slug, plan: "starter" },
    owner.id,
  );
  await subscriptionRepo.insertSubscription(org.id, "starter", "monthly");
