      live.org.id,
      "issue",
      liveIssue.id,
      "drop-me",
      live.project.id,
    );

    await runCleanupArchivedJob(now);

    expect(await orgRepo.findOrgById(expired.org.id)).toBeNull();
    expect(await userRepo.findUserById(expired.userIds.owner)).not.toBeNull();
    for (const table of [
      members,
      invitations,
      projects,
      projectMembers,
      issues,
      labels,
      issueLabels,
      comments,
      attachments,
      notifications,
      notificationPreferences,
      activityEvents,
      subscriptions,
      invoices,
      webhookEndpoints,
      webhookDeliveries,
      searchIndex,
      rateLimitBuckets,
      organizationUsage,
    ]) {
      expect(await rowsFor(table, expired.org.id)).toBe(0);
    }
    const session = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.tokenHash, sessionHash))
      .get();
    expect(session).toBeTruthy();
    expect(session?.activeOrgId).toBeNull();

    await expect(
      restoreOrganization(expired.userIds.owner, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reclaimed = await createOrganization(expired.userIds.owner, {
      name: "Grace expired again",
      slug: expired.org.slug,
      plan: "free",
    });
    expect(reclaimed.slug).toBe(expired.org.slug);

    expect((await orgRepo.findOrgById(young.org.id))?.archivedAt).toBe(youngAt);
    expect(await rowsFor(members, young.org.id)).toBeGreaterThan(0);
    expect(await rowsFor(projects, young.org.id)).toBeGreaterThan(0);
    expect(await orgRepo.listTakenOrgSlugs(young.org.slug)).toContain(
