    );

    expect(await orgRepo.findOrgById(live.org.id)).toBeTruthy();
    expect(
      getDb().select().from(activityEvents).where(eq(activityEvents.id, oldAudit.id)).get(),
    ).toBeUndefined();
    expect(
      getDb().select().from(activityEvents).where(eq(activityEvents.id, recentAudit.id)).get(),
    ).toBeTruthy();
    expect(
      getDb().select().from(issues).where(eq(issues.id, liveIssue.id)).get(),
    ).toBeTruthy();
    expect(
      getDb()
        .select()
        .from(searchIndex)
        .where(eq(searchIndex.subjectId, liveIssue.id))
        .get(),
    ).toBeUndefined();
  });

  it("does not downgrade an ended trial on a deleted workspace", async () => {
    const deleted = await smallTrial("grace-trial-deleted");
    const live = await smallTrial("grace-trial-live");
    await deleteOrganization(deleted.actor, {
      orgId: deleted.orgId,
      confirmSlug: deleted.slug,
    });

    const now = new Date();
    await runTrialExpiryJob(now);

    expect((await subscriptionRepo.findSubscription(deleted.orgId))?.plan).toBe(
      "starter",
    );
    expect((await subscriptionRepo.findSubscription(deleted.orgId))?.status).toBe(
      "trialing",
    );
    expect((await subscriptionRepo.findSubscription(live.orgId))?.plan).toBe("free");
    expect((await subscriptionRepo.findSubscription(live.orgId))?.status).toBe(
      "active",
    );
  });
});

async function smallTrial(slug: string): Promise<{
  orgId: OrgId;
  slug: string;
  actor: Tenant["actors"]["owner"];
}> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });
  const org = await orgRepo.insertOrg(
    { name: slug, slug, plan: "starter" },
    owner.id,
  );
  await subscriptionRepo.insertSubscription(org.id, "starter", "monthly");
  await usageRepo.recomputeUsage(org.id);
  getDb()
    .update(subscriptions)
    .set({
      currentPeriodEnd: toIsoTimestamp(new Date(Date.now() - MS_PER_DAY)),
      status: "trialing",
    })
    .where(eq(subscriptions.orgId, org.id))
    .run();
  return {
    orgId: org.id,
    slug: org.slug,
    actor: { userId: owner.id, orgId: org.id, role: "owner" },
  };
}

