    });

    const now = new Date("2026-08-01T00:00:00.000Z");
    const expiredAt = toIsoTimestamp(new Date(now.getTime() - 30 * MS_PER_DAY));
    const youngAt = toIsoTimestamp(new Date(now.getTime() - 30 * MS_PER_DAY + 1));
    getDb()
      .update(organizations)
      .set({ archivedAt: expiredAt })
      .where(eq(organizations.id, expired.org.id))
      .run();
    getDb()
      .update(organizations)
      .set({ archivedAt: youngAt })
      .where(eq(organizations.id, young.org.id))
      .run();

    await expect(
      restoreOrganization(expired.userIds.owner, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(expired.userIds.admin, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const youngRestored = await restoreOrganization(
      young.userIds.owner,
      young.org.id,
    );
    expect(youngRestored.archivedAt).toBeNull();
    await deleteOrganization(young.actors.owner, {
      orgId: young.org.id,
      confirmSlug: young.org.slug,
    });
    getDb()
      .update(organizations)
      .set({ archivedAt: youngAt })
      .where(eq(organizations.id, young.org.id))
      .run();

    await seedBelongings(expired);
    await seedBelongings(young);

    const sessionHash = "grace-session-hash";
    await sessionRepo.createSession(
      expired.userIds.owner,
      sessionHash,
      toIsoTimestamp(new Date(now.getTime() + MS_PER_DAY)),
    );
    getDb()
      .update(sessions)
      .set({ activeOrgId: expired.org.id })
      .where(eq(sessions.tokenHash, sessionHash))
      .run();

    const oldStamp = toIsoTimestamp(new Date(now.getTime() - 40 * MS_PER_DAY));
    const recentStamp = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
    const oldAudit = await insertActivity({
      orgId: live.org.id,
      action: "issue.created",
      actorId: live.userIds.owner,
      subjectKind: "issue",
      subjectId: "old-live",
      projectId: live.project.id,
      summary: "old",
      metadata: {},
      occurredAt: oldStamp,
    });
    const recentAudit = await insertActivity({
      orgId: live.org.id,
      action: "issue.created",
      actorId: live.userIds.owner,
      subjectKind: "issue",
      subjectId: "recent-live",
      projectId: live.project.id,
      summary: "recent",
      metadata: {},
      occurredAt: recentStamp,
    });
    const liveIssue = await issueService.createIssue(
      live.actors.member,
      issueInput(live.org.id, live.project.id, { title: "Archive me" }),
    );
    await issueService.archiveIssue(live.actors.member, live.org.id, liveIssue.id);
    getDb()
      .update(issues)
      .set({ archivedAt: oldStamp })
      .where(eq(issues.id, liveIssue.id))
      .run();
    await searchRepo.upsertSearchDocument(
      live.org.id,
      "issue",
      liveIssue.id,
      "drop-me",
      live.project.id,
    );

    await runCleanupArchivedJob(now);

    expect(await orgRepo.findOrgById(expired.org.id)).toBeNull();
    expect(await userRepo.findUserById(expired.userIds.owner)).not.toBeNull();
    for (const table of [
      members,
      invitations,
      projects,
      projectMembers,
      issues,
      labels,
      issueLabels,
      comments,
      attachments,
      notifications,
      notificationPreferences,
      activityEvents,
      subscriptions,
      invoices,
      webhookEndpoints,
      webhookDeliveries,
      searchIndex,
      rateLimitBuckets,
      organizationUsage,
    ]) {
      expect(await rowsFor(table, expired.org.id)).toBe(0);
    }
    const session = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.tokenHash, sessionHash))
      .get();
    expect(session).toBeTruthy();
    expect(session?.activeOrgId).toBeNull();

    await expect(
      restoreOrganization(expired.userIds.owner, expired.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reclaimed = await createOrganization(expired.userIds.owner, {
      name: "Grace expired again",
      slug: expired.org.slug,
      plan: "free",
    });
    expect(reclaimed.slug).toBe(expired.org.slug);

    expect((await orgRepo.findOrgById(young.org.id))?.archivedAt).toBe(youngAt);
    expect(await rowsFor(members, young.org.id)).toBeGreaterThan(0);
    expect(await rowsFor(projects, young.org.id)).toBeGreaterThan(0);
    expect(await orgRepo.listTakenOrgSlugs(young.org.slug)).toContain(
      young.org.slug,
    );

    expect(await orgRepo.findOrgById(live.org.id)).toBeTruthy();
    expect(
      getDb().select().from(activityEvents).where(eq(activityEvents.id, oldAudit.id)).get(),
    ).toBeUndefined();
    expect(
      getDb().select().from(activityEvents).where(eq(activityEvents.id, recentAudit.id)).get(),
    ).toBeTruthy();
    expect(
      getDb().select().from(issues).where(eq(issues.id, liveIssue.id)).get(),
    ).toBeTruthy();
    expect(
      getDb()
        .select()
        .from(searchIndex)
        .where(eq(searchIndex.subjectId, liveIssue.id))
        .get(),
    ).toBeUndefined();
  });

  it("does not downgrade an ended trial on a deleted workspace", async () => {
    const deleted = await smallTrial("grace-trial-deleted");
    const live = await smallTrial("grace-trial-live");
    await deleteOrganization(deleted.actor, {
      orgId: deleted.orgId,
      confirmSlug: deleted.slug,
    });

    const now = new Date();
    await runTrialExpiryJob(now);

    expect((await subscriptionRepo.findSubscription(deleted.orgId))?.plan).toBe(
      "starter",
    );
    expect((await subscriptionRepo.findSubscription(deleted.orgId))?.status).toBe(
      "trialing",
    );
    expect((await subscriptionRepo.findSubscription(live.orgId))?.plan).toBe("free");
    expect((await subscriptionRepo.findSubscription(live.orgId))?.status).toBe(
      "active",
    );
  });
});

async function smallTrial(slug: string): Promise<{
  orgId: OrgId;
  slug: string;
  actor: Tenant["actors"]["owner"];
}> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });
  const org = await orgRepo.insertOrg(
    { name: slug, slug, plan: "starter" },
    owner.id,
  );
  await subscriptionRepo.insertSubscription(org.id, "starter", "monthly");
  await usageRepo.recomputeUsage(org.id);
  getDb()
    .update(subscriptions)
    .set({
      currentPeriodEnd: toIsoTimestamp(new Date(Date.now() - MS_PER_DAY)),
      status: "trialing",
    })
    .where(eq(subscriptions.orgId, org.id))
    .run();
  return {
    orgId: org.id,
    slug: org.slug,
    actor: { userId: owner.id, orgId: org.id, role: "owner" },
  };
}

